from pathlib import Path
import re

path = Path("spec/TASKS.md")
text = path.read_text(encoding="utf-8")


def replace_once(old: str, new: str) -> None:
    global text
    if old not in text:
        raise SystemExit(f"missing expected text: {old[:120]!r}")
    text = text.replace(old, new, 1)


def replace_section(start: str, next_start: str, new_section: str) -> None:
    global text
    pattern = re.escape(start) + r".*?(?=\n" + re.escape(next_start) + r")"
    text, count = re.subn(pattern, new_section.rstrip(), text, count=1, flags=re.S)
    if count != 1:
        raise SystemExit(f"failed to replace section: {start}")


